-- =============================================================================
-- StaziaMed, CARGA DAS PROVAS CORRIGIDAS, parte 2 (Revalida 2024/1, revalida-2024-1): texto fiel ao caderno oficial do Inep.
-- Gerado por scripts/carga-provas/gerar-correcoes.mjs (ramo carga-provas). Não edite à mão.
-- O que faz: 25 correções de texto em 17 questões (20 campos: enunciado ou alternativa).
--   * Cada campo só é trocado se o texto no banco ainda é EXATAMENTE o de 12/10/2026 (o que a revisão comparou com o PDF).
--     Se alguém mudou esse texto depois, o campo é PULADO e aparece na lista do fim. Nada é apagado.
--   * O texto antigo fica no histórico da questão (Administração > Questões > Editar > Ver histórico de mudanças), com o motivo.
--   * NÃO mexe em gabarito, situação (anulada), explicações, conduta esperada, "o que a questão avalia", tema, figuras.
--   * Regra do sistema (migração 9500): se a questão tinha Análise Stazia publicada, ela sai do ar (explicava o texto antigo);
--     a contagem aparece no fim.
-- Como colar: editor SQL do Supabase, o arquivo INTEIRO, Run. A primeira linha do resultado começa com "OK:" (ou "ATENÇÃO:" se
-- algum campo foi pulado; mostre ao Claude). Pode colar de novo: a segunda vez não muda nada.
-- =============================================================================
create temp table if not exists _carga_texto_resultado (prova text, questao text, codigo text, campo text, situacao text);
delete from _carga_texto_resultado where prova = 'revalida-2024-1';

do $carga_texto$
declare
  v_dados constant jsonb := $carga_dados$[{"id":"revalida_2024_1_q014","code":"REV-2024.1-Q014","campos":{"statement":{"antes_md5":"cb0d7eaa2c66bc7d54b919de8f7f6be9","depois":"Os dados da carteirinha de uma gestante com 28 anos, primigesta, sem intercorrências clínicas prévias à gestação e que foi atendida em uma unidade básica de saúde, estão transcritos a seguir: DATA IG PA AU BCF/MF OBSERVAÇÕES 15/09 7 sem. 100/70 - -/- Náuseas leves, dor em cólicas discretas. Tabagista 10 cigarros/dia. Pedidos exames de rotina. 12/10 11 sem. 94/62 6 cm -/- Piora nas náuseas, medicada com metoclopramida. Solicito ultrassonografia morfológica. 12/11 15 sem. 100/64 12 cm +/- Melhora nas náuseas, refere corrimento amarelado. Não conseguiu fazer o USG. 09/12 19 sem. 110/72 17 cm +/+ Já percebe MF, sente dor em hipogástrio. 07/01 21 sem. 104/68 20 cm +/+ Sem queixas. 11/02 26 sem. 130/98 24 cm +/+ Solicitado USG morfológica do segundo trimestre. 15/03 31 sem. 140/82 26 cm +/+ Aguarda USG morfológica.Teve sinusiorragia e sangramento ao esforço evacuatório. 12/04 35 sem. 142/88 29 cm +/+ Encaminhada para avaliação no setor de gravidez de alto risco. IG: idade gestacional; PA: pressão arterial sistêmica; AU: altura uterina; MF: movimentação fetal; BCF: batimentos cardíacos fetais; USG: ultrassonografia Com base nesses dados, é correto afirmar que:","sem_tabela_md5":"7de3dec58fcb9f13e2641652d5245029"}}},{"id":"revalida_2024_1_q015","code":"REV-2024.1-Q015","campos":{"D":{"antes_md5":"166c4de274e06aaa25388977996bf202","depois":"Verruga viral; aplicação de ácido tricloroacético (ATA) 80% ou de nitrogênio líquido na UBS."}}},{"id":"revalida_2024_1_q018","code":"REV-2024.1-Q018","campos":{"statement":{"antes_md5":"a63cb134be1ff3d76e0a30c48901d411","depois":"Um neonato, com idade gestacional (IG) de 36 semanas, adequado para IG, com pré-natal regular, nascido de parto normal, APGAR 8/9, apresentou desconforto respiratório com 30 minutos de vida. Ao exame físico, nota-se atividade regular, frequência respiratória de 82 irpm, retrações intercostais e subcostais de moderada intensidade e ausculta pulmonar sem ruídos. Sua saturação de O₂ é de 95% em ar ambiente, sua frequência cardíaca é de 148 bpm e apresenta ritmo cardíaco regular em dois tempos, com bulhas normofonéticas, sem sopros. Além disso, o tempo de enchimento capilar é < 2 segundos; os pulsos estão palpáveis, cheios e simétricos; sua pressão arterial é de 60 x 40 mmHg; e seu fígado está a 2 cm do rebordo costal direito. Com base nessas informações, a conduta médica imediata e adequada para o caso é"},"B":{"antes_md5":"cd1f55df0ec1a7225d9bace3f31ead33","depois":"utilizar cateter de O₂ (2 L/min), realizar hidratação venosa, fisioterapia respiratória e solicitar radiografia de tórax."},"C":{"antes_md5":"79697f8e12373a1ae51a7c08905b1d7b","depois":"realizar intubação endotraqueal, administrar surfactante via endotraqueal e extubar logo após, colocando o neonato sob cateter nasal de O₂ (2 L/min)."},"D":{"antes_md5":"dfa3c395b668f7e2d6869770d13bad37","depois":"realizar ventilação não invasiva com concentração de oxigênio necessária para manter saturação de O₂ igual ou acima de 95% e solicitar radiografia de tórax."}}},{"id":"revalida_2024_1_q021","code":"REV-2024.1-Q021","campos":{"statement":{"antes_md5":"6c52864ed1491a5aae78fafcbb456d79","depois":"Um homem com 38 anos relata, em consulta, exantema, prurido, febre e artralgia que se resolveu em 72 horas com o uso de sintomáticos. O paciente conta que, após 10 dias, passou a apresentar parestesia em membros inferiores, que evoluiu para membros superiores em 24 horas. Ele conta que não buscou ajuda médica por julgar tratar-se de câimbras devido à falta de atividade física regular. Narra, ainda, que, após 3 dias, o quadro evoluiu com fraqueza nos membros inferiores, impedindo a deambulação, queixando-se também de cefaleia holocraniana e obstipação intestinal. Ao exame neurológico, apresenta-se vigil, orientado em tempo e espaço, com pupilas isocóricas e fotorreagentes, mobilidade ocular extrínseca preservada e demais pares cranianos sem alteração. Verificam-se, ainda: força muscular grau V/V em membros superiores e grau III/V em membros inferiores; reflexos bicipital, tricipital e estilorradial grau II/IV; reflexos patelar e aquileu abolidos; hipoestesia tátil e dolorosa nos quatro membros, com padrão de bota e luva; hipopalestesia em membros inferiores, até o tornozelo. O resultado do exame de líquido cefalorraquidiano (LCR) mostrou: EXAME RESULTADO UNIDADES CONVENCIONAIS UNIDADES SI Contagem de células 0 a 2 mm³ 0 a 5 linfócitos/mcL 0 a 5 × 10⁶ linfócitos/L Glicose 74 mg/dL 40 a 80 mg/dL (< 40% do nível plasmático medido simultaneamente se esse nível plasmático está anormal) 2,2 a 4,4 mmol/L (< 40% do nível plasmático medido simultaneamente estão alterados) Proteína total 103 mg/dL 15 a 60 mg/dL 150 a 600 mg/L Diante desse quadro clínico, qual é a principal suspeita diagnóstica?","sem_tabela_md5":"0ae551a91cbb647587e02f310a5095f9"}}},{"id":"revalida_2024_1_q023","code":"REV-2024.1-Q023","campos":{"statement":{"antes_md5":"e0fbd4afa3ae986763369c51026448bf","depois":"Um lactente com 1 mês e 15 dias é trazido pela mãe ao pronto atendimento, a qual relata que seu filho vem apresentando vômitos intensos, em jato e de conteúdo leitoso. Ela nega haver febre associada ao quadro e alega que a criança sempre teve muito refluxo e que os sintomas se intensificaram há 2 semanas. A mãe tem ministrado sintomáticos nos últimos 10 dias, sem melhora, notando que o bebê tem perdido peso. Ao exame, o paciente encontra-se desidratado e sonolento, com abdome escavado, com redução de tecido subcutâneo e com presença de pequena massa móvel palpável em epigástrio. Seus exames laboratoriais revelam gasometria venosa com pH de 7,58 (valor de referência - VR: 7,35 a 7,45); PCO₂ de 41 mmHg (VR: 35 a 45 mmHg); pO₂ de 48,4 mmHg (VR: 80 a 100 mmHg); HCO₃ de 36 mEq/L (VR: 22 a 28 mEq/L); BE de +13,5 (VR: -3 a +3); sódio de 138 mEq/L (VR: 135 a 145 mEq/L); potássio de 3,0 mEq/L (VR: 3,5 a 5 mEq/L); e cloro de 80 mEq/L (VR: 95 a 105 mEq/L). Acerca do caso apresentado e das condutas a serem adotadas, assinale a opção correta."}}},{"id":"revalida_2024_1_q029","code":"REV-2024.1-Q029","campos":{"statement":{"antes_md5":"ed28a3a485b2af7806fbe930685c765f","depois":"Em sua segunda consulta de pré-natal, uma paciente com 36 anos, na 8ª semana da gestação, refere fadiga, ganho de peso, queda de cabelos e pele ressecada. Relata que já teve 2 abortamentos e que, atualmente, está na terceira gestação. Traz resultado de exames laboratoriais cujo único achado relevante foi o de TSH de 8,20 mUI/L (valor de referência - VR = 0,4 a 4,5 mUI/L). Em relação à condição clínica descrita, assinale a opção correta."}}},{"id":"revalida_2024_1_q036","code":"REV-2024.1-Q036","campos":{"statement":{"antes_md5":"0661be315a011bd9600463da29183b1b","depois":"Um homem com 18 anos, residente em área urbana da região Sudeste, sujeita a inundação, chega ao pronto-socorro, durante período de chuvas, queixando-se de febre, mal-estar, mialgia e desconforto abdominal há 1 semana. Refere também que, há 4 dias, sentiu piora da mialgia e surgimento de colúria. Ao exame físico, apresenta-se: em estado geral regular, hidratado, hipocorado (++/4+), ictérico (+++/4+) e com sufusão hemorrágica conjuntival moderada, com temperatura axilar de 38 °C, frequência cardíaca de 110 bpm, pressão arterial de 110 X 70 mmHg. Verificam-se, ainda, dor à palpação dos músculos dos membros inferiores; abdome flácido, doloroso à palpação no hipocôndrio direito e presença de hepatomegalia. Os resultados dos exames laboratoriais registram: EXAME VALOR VALOR DE REFERÊNCIA (VR) Hemograma hematócrito 28% 39,2% a 49,0% hemoglobina 10 g/dL 13,3 a 16,5 d/dL plaquetas 20.000/mm³ 151.000 a 304.000/mm³ bilirrubina total 13 mg/dL 0,2 a 1,2 mg/dL bilirrubina indireta 10 mg/dL ≤ 0,5 mg/dL creatinina 2,9 mg/dL 0,7 a 1,3 mg/dL ureia 70 mg/dL 10 a 45 mg/dL sódio 137 mEq/L 135 a 145 mEq/L potássio 2,0 mEq/L 3,5 a 5,1 mEq/L TGO 90 UI/L 5 a 40 UI/L TGP 80 UI/L 7 a 56 UI/L CPK 1.800 UI/L 30 a 200 UI/L Urina leucócitos mais de 30 por campo < 5 hemácias mais de 100 por campo < 5 urobilinogênio presente ausente cilindros granulosos presentes ausente Diante do quadro clínico e laboratorial descrito, qual é a hipótese diagnóstica mais provável?","sem_tabela_md5":"e91e30ead21f9de1484f7fe815922017"}}},{"id":"revalida_2024_1_q047","code":"REV-2024.1-Q047","campos":{"statement":{"antes_md5":"dc89ddd2bc3631ac6b665ff989c195ed","depois":"Uma mulher com 22 anos procurou serviço hospitalar há 6 horas, com dor periumbilical, em cólica, de forte intensidade. Nesse período de tempo, apresentou um episódio de vômito e manteve anorexia e náusea. Ao exame físico, encontra-se em regular estado geral, com temperatura axilar de 38 °C e dor intensa à descompressão manual brusca em fossa ilíaca direita. No resultado do hemograma, são evidenciados: 14.000 leucócitos/mm³ (valor de referência - VR: 4.000 a 10.000 leucócitos/mm³), bastões 3% (VR: 0 a 5%), segmentados 61% (VR: 40 a 60%). Tomografia computadorizada de abdome mostra apêndice aumentado de volume e densificação da gordura periapendicular. Com base nos dados relatados, assinale a opção que apresenta conduta cirúrgica e uso de antibióticos adequados"}}},{"id":"revalida_2024_1_q053","code":"REV-2024.1-Q053","campos":{"statement":{"antes_md5":"e4594a52309652c43756dcc0e9613436","depois":"Um paciente com Trissomia do 21 (T21) é atendido na unidade básica de saúde para realizar puericultura no 7.º mês de vida. Sua genitora apresenta alguns exames que são registrados no prontuário: ecocardiograma realizado ao nascimento sem qualquer alteração; e hemograma e dosagem dos hormônios tireoidianos solicitados na consulta do 6.º mês, que apresentam valores dentro das referências para a idade. Ao exame físico, observa-se, além das características fenotípicas do paciente, apenas hipotonia global e instabilidade do quadril. Nesse caso, de acordo com o que as diretrizes de acompanhamento ao paciente com T21 recomendam, qual é a conduta médica adequada?"}}},{"id":"revalida_2024_1_q058","code":"REV-2024.1-Q058","campos":{"statement":{"antes_md5":"54abf134d87e19c61a9c455e09fce699","depois":"Uma menina de 4 anos é levada ao pronto-socorro de um hospital público pelo SAMU, com relato de quadro de náusea, vômitos e dor abdominal de evolução rápida nas últimas 6 horas. Sua mãe conta que a filha teve perda de peso significativa na última semana. Ao exame físico, a paciente apresenta-se sonolenta, desidratada, com hálito cetônico, taquicárdica e taquipneica, com glicemia capilar de 300 mg/dL (valor de referência - VR: 60 a 99 mg/dL), gasometria com pH 7,19 (VR: 7,35 a 7,45) e HCO₃ 15 mEq/L (VR: 22 a 28 mEq/L). Com base nos dados apresentados, é correto afirmar que a criança possui níveis reduzidos de"}}},{"id":"revalida_2024_1_q059","code":"REV-2024.1-Q059","campos":{"statement":{"antes_md5":"1d30af170199151130487f33968d8d86","depois":"Uma paciente com 54 anos, G2 P1 C1, com ligadura tubárea bilateral, comparece à consulta ambulatorial com queixa de fogachos, sudorese noturna, insônia, queda da libido, secura vaginal, fadiga e falta de concentração. Sem outras queixas em seu histórico, verifica-se registro de: menarca aos 13 anos; menopausa aos 50 anos; e de tabagismo (consumo de 10 cigarros/dia) desde os 20 anos, além de história patológica pregressa de hipertensão arterial crônica, em uso de losartana 50mg/dia, com bom controle; e história patológica familiar de osteoporose e diabetes mellitus (mãe), hipertensão arterial e infarto agudo do miocárdio aos 60 anos de idade (pai). A paciente apresenta resultados de exames realizados há 6 meses: mamografia digital bilateral: BIRADS 1; Ultrassonografia transvaginal: útero de 40 cm³, endométrio homogêneo e de 3 mm de espessura, ovários atróficos; exames laboratoriais: sem alterações. Ao exame físico, observa-se: índice de massa corpórea: 26,4 kg/m²; pressão arterial: 110 x 70 mmHg; hipotrofia em vagina e colo. Considerando-se o caso clínico descrito, qual é a conduta adequada?"}}},{"id":"revalida_2024_1_q063","code":"REV-2024.1-Q063","campos":{"statement":{"antes_md5":"071ad97be8d940e4627cc680aac8cce0","depois":"Um bebê com 24 dias de vida é levado ao pronto atendimento devido a dificuldades respiratórias. Não houve intercorrências durante a gestação e o parto, o nascimento foi a termo, e o bebê pesou 3 quilogramas. A mãe relata uma história de obstrução nasal, coriza clara e recusa às mamadas há 2 dias. Acrescenta que, nas últimas horas, a respiração do bebê ficou mais rápida e surgiu um chiado no peito. Ao exame físico, o paciente encontra-se em bom estado geral, corado, com frequência respiratória de 50 irpm, com leve tiragem intercostal e sibilos discretos difusos bilateralmente e com saturação de O₂ de 91% em ar ambiente. Na radiografia de tórax, evidenciam-se uma hiperinsuflação pulmonar e retificação das cúpulas diafragmáticas e de arcos costais. Considerando-se a principal hipótese diagnóstica e as condições clínicas do bebê atendido, qual é o tratamento indicado para esse caso?"}}},{"id":"revalida_2024_1_q064","code":"REV-2024.1-Q064","campos":{"statement":{"antes_md5":"b04355b6a0032af2beeca8359e763cc9","depois":"Uma mulher com 30 anos procura o médico na unidade básica de saúde e, em consulta, relata que, há 9 meses, parou de usar o anticoncepcional oral combinado e que não voltou a menstruar até o momento. Refere também uso desse método contraceptivo por 10 anos e aumento de pelos no corpo. O exame ginecológico, apresenta-se normal. No exame físico, verificam-se: índice de massa corporal de 27 kg/m²; pressão arterial de 110 x 72 mmHg; cintura abdominal de 80 cm; acne e hirsutismo moderado. Os exames complementares apresentam os seguintes resultados: Beta-hCG negativo; TSH = 2,5 mUI/L (valor de referência - VR: 0,3 a 4,0 UI/L); prolactina = 18 ng/mL (VR: < 31 ng/mL); FSH = 6 mUI/mL (VR: 2 a 30 mUI/mL). Diante do quadro clínico da paciente, o diagnóstico é de amenorreia secundária por"}}},{"id":"revalida_2024_1_q077","code":"REV-2024.1-Q077","campos":{"statement":{"antes_md5":"4322dc0dec1379b9e6bb53e6be999ca5","depois":"Um paciente com 57 anos, queixa-se, em consulta, de dor abdominal difusa intermitente, há 3 meses, que piora com ingestão de alimentos, associada a emagrecimento de 9 quilogramas nesse período, além de diarreia com gotículas de gordura nas fezes. É tabagista e etilista há 30 anos. Ao exame físico, apresenta dor abdominal difusa que piora à palpação profunda em região mesogástrica, sem outras particularidades. EXAMES LABORATORIAIS EXAME VALOR VALOR DE REFERÊNCIA (VR) hemoglobina 10,5 g/dL 13 a 17 g/dL hematócrito 35% 40% a 50% leucócitos 8.000 mm³ 4.000 a 10.000 mm³ glicemia jejum 155 mg/dL <100 mg/dL AST 39 U/L <38 U/L ALT 33 U/L <41 U/L bilirrubina total 1,1 mg/dL 0,2 mg/dL a 1,20 mg/dL amilase 130 U/L 25 a 125 U/L lipase 83 U/L <60 U/L ureia 42 mg/dL <45 mg/dL creatinina 1,3 mg/dL 0,6 a 1,2 mg/dL cálcio sérico 10,4 mg/dL 8,6 a 10 mg/dL Com base no quadro acima, quais são, respectivamente, o diagnóstico e a conduta para o paciente?","sem_tabela_md5":"c07de23398f0711f61120b6eb4d7b28a"}}},{"id":"revalida_2024_1_q088","code":"REV-2024.1-Q088","campos":{"statement":{"antes_md5":"ffef852e6538c0e7c6a50f11e48fb250","depois":"Um lactente com 5 meses é levado à emergência por seus pais com quadro de rinorreia hialina, tosse leve e febre baixa (37,9 °C) de início há 24 horas. Eles relatam que, há algumas horas, o bebê passou a apresentar rouquidão, tosse persistente e ruídos inspiratórios mesmo em repouso. Ao exame físico, constata-se que a criança está agitada, com desconforto respiratório, com tiragem intercostal discreta e com estridor inspiratório. Sua frequência cardíaca é de 110 bpm, sua frequência respiratória é de 42 irpm e sua saturação de O₂ é de 96% em ar ambiente. Durante a ausculta, nota-se boa entrada de ar bilateralmente. A expansibilidade torácica está preservada. Observa-se, entretanto, cianose quando a criança fica muito agitada. Diante dessas informações, a conduta médica adequada é prescrever"}}},{"id":"revalida_2024_1_q091","code":"REV-2024.1-Q091","campos":{"statement":{"antes_md5":"486c2369377573616294b7f7b1911886","depois":"Um paciente com 34 anos, em tratamento quimioterápico para linfoma, é avaliado no plantão de um hospital com queixa de dispneia, desconforto torácico, ortopneia, com progressão nas últimas 6 horas. Ao exame físico, apresenta-se em regular estado geral, com frequência cardíaca de 125 bpm, frequência respiratória de 28 irpm, saturação de O₂ de 93% em ar ambiente, pressão arterial de 86 x 48 mmHg. Durante a inspiração, observa-se que a pressão sistólica reduziu para 75 x 44 mmHg. A temperatura axilar do paciente é de 36,6 °C e ele apresenta grande distensão jugular, bulhas cardíacas hipofonéticas. O exame de ECG no leito indicou baixa voltagem dos complexos QRS, sem presença de alterações isquêmicas detectáveis. Os resultados de outros exames realizados nesse dia são: EXAMES LABORATORIAIS EXAME VALOR VALOR DE REFERÊNCIA (VR) hematócrito 28% 40% a 50% hemoglobina 7,3 g/dL 13 a 17 g/dL leucócitos 5.500 mm³ 4.000 a 10.000 mm³ neutrófilos 70% 40% a 80% plaquetas 62.000 151.000 a 304.000/mm³ protrombina 2,2 0,8 a 1,2 ácido úrico 6,9 mg/dL 2,4 a 5,7 mg/dL glicemia jejum 155 mg/dL <100 mg/Dl creatinina 0,6 mg/dL 0,6 a 1,2 mg/dL bilirrubina total 0,9 mg/dL 0,2 a 1,20 mg/dL lactato 1,5 0,5 a 1,6 mmol/L Considerando a hipótese diagnóstica mais provável, assinale a opção com as medidas mais adequadas a serem adotadas para esse paciente.","sem_tabela_md5":"0736ef6fc276db6ff240141ff71cee65"}}},{"id":"revalida_2024_1_q095","code":"REV-2024.1-Q095","campos":{"C":{"antes_md5":"f1d8cb9de592145ac0b4c36379c111e0","depois":"Realizar prova do laço e otoscopia; e prescrever hidratação oral à paciente, orientando o retorno no dia de melhora da febre ou no 5.º dia após a consulta, se não melhorar."}}}]$carga_dados$::jsonb;
  r jsonb;
  c record;
  q public.questions;
  v_statement text;
  v_options jsonb;
  v_atual text;
  v_situacao text;
  v_muda boolean;
  v_analises integer := 0;
begin
  perform set_config('sqie.reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)', true);
  for r in select value from jsonb_array_elements(v_dados) loop
    select * into q from public.questions x where x.id = r ->> 'id' for update;
    if not found then
      insert into _carga_texto_resultado values ('revalida-2024-1', r ->> 'id', r ->> 'code', '-', 'pulado: questão não encontrada no banco');
      continue;
    end if;
    v_statement := q.statement;
    v_options := q.options;
    v_muda := false;
    for c in select key as campo, value as v from jsonb_each(r -> 'campos') loop
      v_atual := case when c.campo = 'statement' then q.statement
                      else (select o ->> 'text' from jsonb_array_elements(q.options) o where o ->> 'id' = c.campo limit 1) end;
      if v_atual is not distinct from (c.v ->> 'depois') or md5(v_atual) is not distinct from (c.v ->> 'sem_tabela_md5') then
        v_situacao := 'já estava corrigido';
      elsif v_atual is not null and md5(v_atual) = c.v ->> 'antes_md5' then
        v_situacao := 'corrigido agora';
        v_muda := true;
        if c.campo = 'statement' then
          v_statement := c.v ->> 'depois';
        else
          v_options := (select jsonb_agg(case when o ->> 'id' = c.campo then jsonb_set(o, '{text}', to_jsonb(c.v ->> 'depois')) else o end order by n)
                        from jsonb_array_elements(v_options) with ordinality as x (o, n));
        end if;
      else
        v_situacao := 'pulado: o texto no banco mudou depois de 12/10/2026';
      end if;
      insert into _carga_texto_resultado values ('revalida-2024-1', q.id, q.code, case c.campo when 'statement' then 'enunciado' else 'alternativa ' || c.campo end, v_situacao);
    end loop;
    if v_muda then
      v_analises := v_analises + (select count(*)::int from public.question_analysis a where a.question_id = q.id and a.is_current and a.status = 'published');
      update public.questions set statement = v_statement, options = v_options where id = q.id;
      perform public.admin_log('question.updated', q.id, jsonb_build_object('status', q.status, 'reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)'));
    end if;
  end loop;
  insert into _carga_texto_resultado values ('revalida-2024-1', '-', '-', 'análises', 'análises publicadas que saíram do ar: ' || v_analises);
  perform set_config('sqie.reason', '', true);
end
$carga_texto$;

select resultado, detalhe from (
  select 0 as ordem,
         case when count(*) filter (where situacao like 'pulado%') = 0 then 'OK: ' else 'ATENÇÃO: ' end
           || 'Revalida 2024/1: '
           || count(distinct questao) filter (where situacao = 'corrigido agora') || ' questões corrigidas agora ('
           || count(*) filter (where situacao = 'corrigido agora') || ' campos); '
           || count(*) filter (where situacao = 'já estava corrigido') || ' campos já estavam corrigidos; '
           || count(*) filter (where situacao like 'pulado%') || ' pulados (de 20)' as resultado,
         max(situacao) filter (where campo = 'análises') as detalhe
  from _carga_texto_resultado where prova = 'revalida-2024-1'
  union all
  select 1, 'PULADO: ' || codigo || ' (' || campo || ')', situacao
  from _carga_texto_resultado where prova = 'revalida-2024-1' and situacao like 'pulado%'
) x order by ordem, resultado;
